update orders
set status = #{status}
where order_no = #{orderNo} and deleted = 0 and status = #{expectStatus}

update orders
set status = #{status}, pay_type = #{payType}, paid_at = #{paidAt}
where order_no = #{orderNo} and deleted = 0 and status = #{expectStatus}

update orders
set status = #{status}, cancelled_at = #{cancelledAt}, cancel_reason = #{cancelReason}
where order_no = #{orderNo} and deleted = 0 and status = #{expectStatus}
